type BinaryOp = (a: number, b: number) => number;

const add: BinaryOp = (a, b) => a + b;
const sub: BinaryOp = function (a, b) { return a - b; }; // OK — value can be either

class Timer {
  private ms = 1000;

  startMethod() {
    setTimeout(function () {
      console.log(this.ms); // Error: this is void/any
    }, this.ms);
  }

  startArrow() {
    setTimeout(() => {
      console.log(this.ms); // OK — lexical this is Timer
    }, this.ms);
  }
}

const double = (n: number) => n * 2;

const parse = (raw: string): number | null => {
  const n = Number(raw);
  return Number.isNaN(n) ? null : n;
};

const Person = (name: string) => {
  this.name = name; // Error: arrow cannot have this param / constructor
};
